{"sql": "SELECT COUNT(*) as unmatched FROM (
  SELECT DISTINCT t.start_station_id FROM `bigquery-public-data.austin_bikeshare.bikeshare_trips` t
  WHERE EXTRACT(YEAR FROM t.start_time) IN (2013, 2014)
  AND t.start_station_id NOT IN (SELECT station_id FROM `bigquery-public-data.austin_bikeshare.bikeshare_stations`)
)"}
